mapper.select:
select analysis_id, tenant_id, user_id, message_external_id, provider, external_name,
       locale, subject, sender, body_hash,
       executive_summary, category, urgency,
       sentiment_label, sentiment_score, sentiment_description,
       detected_intent, suggested_action,
       entities_json, suggested_ticket_json, suggested_lead_json, analysis_json, model,
       del_flag, create_by, create_time, update_by, update_time
from crm_email_analysis
where tenant_id = #{tenantId}
  and message_external_id = #{messageExternalId}
  and locale = #{locale}
  and del_flag = '0'

  and provider = #{provider}


  and external_name = #{externalName}

order by update_time desc
limit 1
